; rmt_feat.s - ca65 version of asm/Patch-16/rmt_feat.a65
; Generated by scripts/mads2ca65.py: edit the MADS source and run the script again.

;
; RMT FEATures definitions
;
; For optimizations of RMT player routine to concrete RMT module only!

; ------------------------------------------------------------------------------------------------------------

; PATCH16 ADDITIONS BY VINSCOOL, USE ONLY IF YOU KNOW WHAT YOU ARE DOING!

; The target selectors FEAT_IS_TRACKER and FEAT_IS_SIMPLEP are defined on the command line, not here,
; so this file stays xasm-compatible (xasm has no .ifndef to express an overridable default):
; - FEAT_IS_TRACKER=1 FEAT_IS_SIMPLEP=0 if the target output is the actual RMT driver binary (tracker.obx)
; - FEAT_IS_TRACKER=0 FEAT_IS_SIMPLEP=1 for the Simple RMT Player, a simple recreation of the original
;   .xex export player from RMT, with few bonus features
; build.cmd passes them with -d: (MADS); for xasm the same values are /d:FEAT_IS_TRACKER=1 /d:FEAT_IS_SIMPLEP=0.

	.assert !((FEAT_IS_TRACKER+FEAT_IS_SIMPLEP)=0), error, "ERT [FEAT_IS_TRACKER+FEAT_IS_SIMPLEP]=0"	; The RMT driver has no driver parameter defined!
	.assert !((FEAT_IS_TRACKER+FEAT_IS_SIMPLEP)=2), error, "ERT [FEAT_IS_TRACKER+FEAT_IS_SIMPLEP]=2"	; The RMT driver could not have more than 1 driver parameter defined!

.if FEAT_IS_TRACKER	; Must be defined to work around some undefined labels...
.ifndef EXPORTXEX
EXPORTXEX = 0
.endif
.ifndef EXPORTSAP
EXPORTSAP = 0
.endif
.endif

; ------------------------------------------------------------------------------------------------------------

; STEREO MODE MUST ALWAYS BE 1 IF THE OUTPUT IS INTENDED FOR USE AS RMT DRIVER BINARY, ELSE IT WILL BE BROKEN!

.if FEAT_IS_TRACKER
.ifndef STEREOMODE
STEREOMODE = 1
.endif
.elseif !FEAT_IS_SIMPLEP	; dasmplayer.asm has its own definition there so it could be ignored here
.ifndef STEREOMODE
STEREOMODE = 0
.endif
									; 0 => compile RMTplayer for 4 tracks mono
									; 1 => compile RMTplayer for 8 tracks stereo
									; 2 => compile RMTplayer for 4 tracks stereo L1 R2 R3 L4
									; 3 => compile RMTplayer for 4 tracks stereo L1 L2 R3 R4
									; 4 => compile RMTplayer for 8 tracks Dual Mono LR1 LR2 LR3 LR4
.endif

; Stereo mode may also be defined from a different location (game/demo, dasmplayer.asm, etc), comment it out if necessary

